const rep = $json;
const content = (((rep.choices || [])[0] || {}).message || {}).content || "";
const m = content.match(/\{[\s\S]*\}/);
let parsed = {}, parseOk = false;
try { if (m) { parsed = JSON.parse(m[0]); parseOk = !!parsed && typeof parsed === "object"; } } catch (e) { parsed = {}; }
const ev = $('Normaliser la demande').item.json;
function norm(s) {
  return (s || "").toString().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/[^a-z0-9° ]/g, " ").replace(/\s+/g, " ").trim();
}
const INTERDITS = ["meilleur","le plus","la plus","les plus","n°1","no 1","imbattable","exceptionnel","moins cher","prix bas","petit prix","pas cher","bio","biologique","label","certifié","certifie","garanti","une seule séance","une seule seance","gueri","guerison"];
const SANTE = ["soulage","retrouver votre forme","retrouve ta forme","resultat"];
const liste = /sant/i.test(ev.categorie || "") ? INTERDITS.concat(SANTE) : INTERDITS;
// Correspondance par mots entiers (singulier ou pluriel) : évite que « bio » bloque « biographie »
function interditDans(texte) {
  const n = " " + norm(texte) + " ";
  return liste.find(w => { const k = norm(w); return n.includes(" " + k + " ") || n.includes(" " + k + "s "); }) || null;
}
function nettoyer(v) {
  if (!v || typeof v !== "string") return "";
  let t = v.trim();
  if (t.length > 300) t = t.slice(0, 300);
  return t;
}
let v1 = nettoyer(parsed.v1), v2 = nettoyer(parsed.v2);
const b1 = interditDans(v1), b2 = interditDans(v2);
if (b1) v1 = "";
if (b2) v2 = "";
const versions = [v1, v2].filter(Boolean);
let alerte = (typeof parsed.alerte === "string" ? parsed.alerte : "").trim();
if (!alerte) {
  if (!parseOk) alerte = "réponse IA illisible : correction impossible";
  else if (versions.length === 0) alerte = "correction IA impossible (mots interdits CP-10 ou texte inexploitable)";
  else if (b1 || b2) alerte = "une version IA écartée (mot interdit CP-10 : " + (b1 || b2) + ")";
}
return { json: {
  proposition_id: ev.proposition_id,
  version_ia_1: v1,
  version_ia_2: v2,
  nb_versions: versions.length,
  alerte_moderation: alerte,
  bloque_v1: b1, bloque_v2: b2
} };
